package jp.sakai.fanza.link;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.view.*;import android.widget.*;
public class MainActivity extends Activity{EditText data,link;public void onCreate(Bundle b){super.onCreate(b);LinearLayout x=new LinearLayout(this);x.setOrientation(LinearLayout.VERTICAL);x.setPadding(32,28,32,28);x.addView(t("② アフィリエイトリンク準備",24));x.addView(t("①でコピーした作品情報を読み込み、リンクを確認します。作品情報は消しません。",15));data=e("作品情報");data.setMinLines(7);x.addView(data);Button r=btn("クリップボード読込");r.setOnClickListener(v->load());x.addView(r);link=e("アフィリエイトURL");x.addView(link);Button c=btn("リンクを確認して作品情報を再コピー");c.setOnClickListener(v->copy());x.addView(c);setContentView(x);getWindow().setStatusBarColor(Color.rgb(216,27,96));}
TextView t(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setPadding(0,10,0,10);return v;}EditText e(String h){EditText v=new EditText(this);v.setHint(h);v.setTextSize(16);return v;}Button btn(String s){Button b=new Button(this);b.setText(s);b.setTextSize(16);return b;}void load(){ClipboardManager m=(ClipboardManager)getSystemService(CLIPBOARD_SERVICE);if(!m.hasPrimaryClip()){toast("コピーされたデータがありません");return;}String s=m.getPrimaryClip().getItemAt(0).coerceToText(this).toString();data.setText(s);link.setText(field(s,"AFFILIATE:"));}String field(String s,String k){for(String l:s.split("\n"))if(l.startsWith(k))return l.substring(k.length()).trim();return "";}void copy(){String l=link.getText().toString().trim();if(!l.startsWith("http")){toast("アフィリエイトURLがありません");return;}String s=data.getText().toString();if(s.contains("AFFILIATE:"))s=s.replaceAll("(?m)^AFFILIATE:.*$","AFFILIATE: "+l);((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("FANZA作品情報",s));toast("確認済み。次は③を開いてください");}void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}}
